#!/usr/bin/env node
// HX-01: the client's copy of the helper feature index ids (smartsched/backend/app/ai/helper/features.yaml, HB-01).
// The server never sends a URL: a `nav` card carries `feature_id`, and the client maps it to the route, the anchor
// and the permission from this generated table (components/helper/feature-links.ts).
//
//   node scripts/gen-helper-features.mjs            # rewrites src/components/helper/feature-index.gen.ts
//   node scripts/gen-helper-features.mjs --check    # exit 1 when the generated file is out of date
//
// The YAML is read with a small parser for the subset the index uses (a list of flat entries whose values are
// scalars, one-line flow maps `{tr: …, en: …}` and flow lists `[a, b]`); block keys (synonyms, steps) are skipped.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
export const FEATURES_PATH = resolve(here, "../../backend/app/ai/helper/features.yaml");
export const OUT_PATH = resolve(here, "../src/components/helper/feature-index.gen.ts");

/** Parse one flow value: `[a, "b c"]`, `{tr: x, en: [y]}`, a quoted or plain scalar. */
export function parseFlow(text) {
  let i = 0;
  const ws = () => {
    while (i < text.length && /\s/.test(text[i])) i++;
  };
  const scalar = (stops) => {
    ws();
    if (text[i] === '"' || text[i] === "'") {
      const q = text[i++];
      let out = "";
      while (i < text.length && text[i] !== q) {
        if (q === '"' && text[i] === "\\") i++;
        out += text[i++];
      }
      i++;
      return out;
    }
    let out = "";
    while (i < text.length && !stops.includes(text[i])) out += text[i++];
    return out.trim();
  };
  const value = (stops) => {
    ws();
    if (text[i] === "[") {
      i++;
      const list = [];
      ws();
      if (text[i] === "]") {
        i++;
        return list;
      }
      for (;;) {
        list.push(value([",", "]"]));
        ws();
        if (text[i] === ",") i++;
        else if (text[i] === "]") {
          i++;
          return list;
        } else throw new Error(`bad flow list: ${text}`);
      }
    }
    if (text[i] === "{") {
      i++;
      const map = {};
      for (;;) {
        ws();
        if (text[i] === "}") {
          i++;
          return map;
        }
        const key = scalar([":"]);
        i++; // ':'
        map[key] = value([",", "}"]);
        ws();
        if (text[i] === ",") i++;
      }
    }
    return scalar(stops);
  };
  const out = value([]);
  return out;
}

const FIELDS = ["id", "kind", "route", "title", "path", "anchor", "permission", "hide_with", "actions"];

/** The index entries with the fields the client needs (pure: the test runs it on the YAML). */
export function parseFeatures(yaml) {
  const entries = [];
  let cur = null;
  for (const raw of yaml.split("\n")) {
    if (/^\s*#/.test(raw) || !raw.trim()) continue;
    const start = /^- id:\s*(.+)$/.exec(raw);
    if (start) {
      cur = { id: start[1].trim() };
      entries.push(cur);
      continue;
    }
    const m = /^ {2}([a-z_]+):\s*(.*)$/.exec(raw);
    if (!m || !cur) continue;
    const [, key, rest] = m;
    if (!FIELDS.includes(key) || rest === "") continue;
    cur[key] = parseFlow(rest);
  }
  return entries.map((e) => ({
    id: e.id,
    kind: e.kind,
    route: e.route,
    title: e.title,
    path: e.path,
    anchor: e.anchor ?? null,
    permission: e.permission ?? [],
    hideWith: e.hide_with ?? null,
    actions: e.actions ?? [],
  }));
}

export function generate(yaml) {
  const entries = parseFeatures(yaml);
  const rows = entries.map((e) => `  ${JSON.stringify(e)},`);
  return [
    "// GENERATED by scripts/gen-helper-features.mjs from smartsched/backend/app/ai/helper/features.yaml (HB-01).",
    "// Do not edit: run `node scripts/gen-helper-features.mjs` after the index changes; feature-links.test.ts fails",
    "// while this file is out of date.",
    "",
    'export type FeatureKind = "page" | "tab" | "setting" | "control";',
    "export interface FeatureEntry {",
    "  id: string;",
    "  kind: FeatureKind;",
    "  /** a page path, optionally with #section */",
    "  route: string;",
    "  title: { tr: string; en: string };",
    "  path: { tr: string[]; en: string[] };",
    "  /** a `data-tour` id (welcome-guide.md §13, helper.md §3.4) */",
    "  anchor: string | null;",
    "  /** any-of; empty = every signed-in person */",
    "  permission: string[];",
    "  /** hidden for holders of this permission (NavItem.hideWith) */",
    "  hideWith: string | null;",
    "  actions: string[];",
    "}",
    "",
    "export const FEATURE_INDEX: readonly FeatureEntry[] = [",
    ...rows,
    "];",
    "",
  ].join("\n");
}

function main() {
  const out = generate(readFileSync(FEATURES_PATH, "utf8"));
  if (process.argv.includes("--check")) {
    if (readFileSync(OUT_PATH, "utf8") !== out) {
      console.error("feature-index.gen.ts is out of date: run node scripts/gen-helper-features.mjs");
      process.exit(1);
    }
    console.log("feature-index.gen.ts is up to date");
    return;
  }
  writeFileSync(OUT_PATH, out);
  console.log(`wrote ${OUT_PATH}`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
